//! Locale resolution and runtime switching.
//!
//! `rust-i18n` embeds the YAML generated by `scripts/export-i18n.mjs`. Locale
//! changes also reach the Kit's own component strings (menus, dialogs) through
//! `gpui_kit::component::set_locale`.

use gpui_kit::SharedString;
use rust_i18n::t;

/// The eight locales the 2.x app ships. Keep this list and the
/// `languages.*` keys in sync; the parity test reads both.
pub const SUPPORTED_LOCALES: [&str; 8] = ["en", "fr", "pt-BR", "zh-CN", "zh-TW", "ru", "id", "ar"];

pub const DEFAULT_LOCALE: &str = "en";

pub fn is_supported(locale: &str) -> bool {
    SUPPORTED_LOCALES
        .iter()
        .any(|candidate| candidate.eq_ignore_ascii_case(locale))
}

/// Maps the OS locale to one of the bundled catalogs.
pub fn system_locale() -> &'static str {
    let Some(raw) = sys_locale::get_locale() else {
        return DEFAULT_LOCALE;
    };
    let lower = raw.to_ascii_lowercase();
    if lower.starts_with("pt") {
        return "pt-BR";
    }
    if lower.starts_with("zh") {
        return if lower.contains("tw") || lower.contains("hk") || lower.contains("hant") {
            "zh-TW"
        } else {
            "zh-CN"
        };
    }
    if let Some(exact) = SUPPORTED_LOCALES
        .iter()
        .find(|candidate| candidate.eq_ignore_ascii_case(&lower))
    {
        return exact;
    }
    DEFAULT_LOCALE
}

/// A saved preference wins only when it is still supported.
pub fn resolve(preferred: &str) -> &'static str {
    if let Some(exact) = SUPPORTED_LOCALES
        .iter()
        .find(|candidate| candidate.eq_ignore_ascii_case(preferred))
    {
        return exact;
    }
    system_locale()
}

pub fn next(current: &str) -> &'static str {
    let index = SUPPORTED_LOCALES
        .iter()
        .position(|candidate| candidate.eq_ignore_ascii_case(current))
        .unwrap_or(0);
    SUPPORTED_LOCALES[(index + 1) % SUPPORTED_LOCALES.len()]
}

/// Applies the locale to both catalogs. Call from an event, never from render.
pub fn apply(locale: &str) {
    rust_i18n::set_locale(locale);
    gpui_kit::component::set_locale(locale);
}

/// Localized endonym, e.g. `Português (Brasil)`.
pub fn label(locale: &str) -> SharedString {
    match locale {
        "fr" => t!("languages.fr").to_string().into(),
        "pt-BR" => t!("languages.pt-BR").to_string().into(),
        "zh-CN" => t!("languages.zh-CN").to_string().into(),
        "zh-TW" => t!("languages.zh-TW").to_string().into(),
        "ru" => t!("languages.ru").to_string().into(),
        "id" => t!("languages.id").to_string().into(),
        "ar" => t!("languages.ar").to_string().into(),
        _ => t!("languages.en").to_string().into(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_catalog_resolves_keys() {
        rust_i18n::set_locale("en");
        assert_eq!(t!("controlPanel.screen").as_ref(), "Screen");
        assert_eq!(t!("languages.pt-BR").as_ref(), "Português (Brasil)");
    }

    #[test]
    fn every_locale_has_a_label() {
        for locale in SUPPORTED_LOCALES {
            let label = label(locale);
            assert!(
                !label.is_empty() && label.as_ref() != locale,
                "{locale} label is missing"
            );
        }
    }

    #[test]
    fn resolves_unknown_and_regional_locales() {
        assert_eq!(resolve("xx-YY"), system_locale());
        assert_eq!(resolve("PT-br"), "pt-BR");
        assert_eq!(resolve("fr"), "fr");
    }

    #[test]
    fn next_wraps_around_the_catalog() {
        assert_eq!(next("en"), "fr");
        assert_eq!(next("ar"), "en");
        assert_eq!(next("unknown"), "fr");
    }
}
